using BlaxtorGym.src.BlaxtorGym.Domain.Entities; using BlaxtorGym.src.BlaxtorGym.Domain.Interfaces; using BlaxtorGym.src.BlaxtorGym.Infraestructure.Data; using Microsoft.EntityFrameworkCore;
namespace BlaxtorGym.src.BlaxtorGym.Infraestructure.Repositories;
public class BitacoraRepository : IBitacoraRepository { private readonly AppDbContext _context; public BitacoraRepository(AppDbContext context) => _context = context; public async Task AgregarAsync(BitacoraCambio cambio) { await _context.BitacoraCambios.AddAsync(cambio); await _context.SaveChangesAsync(); } public async Task<List<BitacoraCambio>> ObtenerAsync(DateTime? i, DateTime? f, string? a, string? e, int? u) { var q = _context.BitacoraCambios.Include(x => x.Usuario).AsNoTracking().AsQueryable(); if (i.HasValue) q = q.Where(x => x.FechaHora >= i.Value.Date); if (f.HasValue) q = q.Where(x => x.FechaHora < f.Value.Date.AddDays(1)); if (!string.IsNullOrWhiteSpace(a)) q = q.Where(x => x.Accion == a); if (!string.IsNullOrWhiteSpace(e)) q = q.Where(x => x.Entidad == e); if (u.HasValue) q = q.Where(x => x.UsuarioId == u.Value); return await q.OrderByDescending(x => x.FechaHora).ToListAsync(); } }
